<?php
namespace Tests\Feature;
use App\Models\{User,Idea};
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\DB;
class AdministrationTest extends \Illuminate\Foundation\Testing\TestCase {
 use RefreshDatabase;
 public function createApplication(){ $app=require __DIR__.'/../../bootstrap/app.php';$app->make(\Illuminate\Contracts\Console\Kernel::class)->bootstrap();return $app;}
 private function user(string $role='Programme Administrator',?int $programme=null):User {$u=new User(['name'=>'Example Staff','email'=>uniqid().'@example.test','password'=>'Test-password-123']);$u->save();DB::table('programme_role_user')->insert(['user_id'=>$u->id,'role_id'=>DB::table('roles')->where('name',$role)->value('id'),'programme_id'=>$programme??$this->pid()]);$this->withSession(['mfa_user_id'=>$u->id]);return $u->fresh();}
 public function actingAs(\Illuminate\Contracts\Auth\Authenticatable $user,$guard=null){$this->withSession(['mfa_user_id'=>$user->getAuthIdentifier(),'mfa_verified_at'=>time()]);return parent::actingAs($user,$guard);}
 private function pid():int{return DB::table('programmes')->value('id');}
 private function master():User{$u=$this->user();$u->is_master=true;$u->save();return $u->fresh();}
 private function role(string $name):int{return DB::table('roles')->where('name',$name)->value('id');}
 private function idea():Idea{return Idea::create(['title'=>'Business idea','team'=>'Applicant','initial'=>'A','category'=>'Service','location'=>'Gaborone','color'=>'#fff','ink'=>'#000','submitted_at'=>now(),'summary'=>'Summary','problem'=>'Problem','solution'=>'Solution','status'=>'ready','complete'=>100,'checks'=>[false,false,false,false],'programme_id'=>$this->pid()]);}
 private function template(string $kind):int{return DB::table('review_templates')->insertGetId(['programme_id'=>$this->pid(),'name'=>'Criteria','kind'=>$kind,'version'=>1,'criteria'=>json_encode([['name'=>'Innovation','max'=>10]]),'active'=>true,'created_at'=>now(),'updated_at'=>now()]);}
 private function allocation():array{$e=$this->user('Evaluator');$a=$this->user('Adjudicator');return ['evaluator_ids'=>[$e->id],'adjudicator_id'=>$a->id,'lead_id'=>$e->id,'template_id'=>$this->template('evaluation'),'adjudication_template_id'=>$this->template('adjudication'),'due_date'=>now()->addDays(2)->format('Y-m-d')];}
 public function test_reviewer_mfa_switch_is_limited_to_reviewer_roles():void{config(['portal.reviewer_mfa_enabled'=>false,'portal.master_mfa_enabled'=>true]);foreach(['Evaluator','Adjudicator'] as $role){$reviewer=$this->user($role);$this->assertFalse(\App\Services\Administration::requiresMfa($reviewer));$this->actingAs($reviewer)->withSession(['mfa_user_id'=>null])->getJson('/api/v1/me')->assertJsonPath('user.mfa_required',false);} $admin=$this->user();$this->assertTrue(\App\Services\Administration::requiresMfa($admin));}
 public function test_application_pages_stop_at_ten_records():void{
  for($index=0;$index<15;$index++)$this->idea();
  $this->actingAs($this->user());
  $first=$this->getJson('/api/v1/applications?stage=ready&page=1')->assertOk()->assertJsonCount(10,'data')->assertJsonPath('meta.total',15)->json();
  $second=$this->getJson('/api/v1/applications?stage=ready&page=2')->assertOk()->assertJsonCount(5,'data')->json();
  $this->assertEmpty(array_intersect(array_column($first['data'],'id'),array_column($second['data'],'id')));
  $this->getJson('/api/v1/applications?per_page=11')->assertUnprocessable();
 }
 public function test_guest_and_non_manager_access_denied():void{$this->getJson('/api/v1/people')->assertUnauthorized();$this->actingAs($this->user('Evaluator'))->getJson('/api/v1/people')->assertForbidden();}
 public function test_master_creates_account_and_activation_is_single_use():void{$master=$this->master();$r=$this->actingAs($master)->postJson('/api/v1/people',['name'=>'New Reviewer','email'=>'new@example.test','type'=>'staff','programme_id'=>$this->pid(),'role_ids'=>[$this->role('Evaluator')],'mode'=>'create'])->assertCreated();parse_str(parse_url($r->json('activation_url'),PHP_URL_QUERY),$q);$this->assertDatabaseHas('users',['email'=>'new@example.test','account_status'=>'invited']);$body=['token'=>$q['token'],'password'=>'NewPass123!','password_confirmation'=>'NewPass123!','confidentiality'=>true];$this->postJson('/api/v1/activate',$body)->assertOk();$this->postJson('/api/v1/activate',$body)->assertUnprocessable();$this->assertDatabaseHas('audit_events',['action'=>'invitation.accepted']);}
 public function test_people_management_is_limited_to_staff_accounts():void{$master=$this->master();$manager=$this->user();$applicant=$this->user('Viewer');$applicant->member_type='applicant';$applicant->save();$external=$this->user('Evaluator');$external->member_type='external';$external->save();foreach([$master,$manager] as $actor){$this->actingAs($actor)->getJson('/api/v1/people')->assertOk()->assertJsonMissing(['email'=>$applicant->email])->assertJsonMissing(['email'=>$external->email]);foreach([$applicant,$external] as $target){$this->patchJson('/api/v1/people/'.$target->id,['action'=>'suspend'])->assertNotFound();$this->getJson('/api/v1/people/'.$target->id.'/history')->assertNotFound();}}$this->actingAs($master)->postJson('/api/v1/people',['name'=>'External','email'=>'another-external@example.test','type'=>'external','programme_id'=>$this->pid(),'role_ids'=>[$this->role('Evaluator')],'mode'=>'invite'])->assertUnprocessable();$this->assertDatabaseHas('users',['id'=>$applicant->id,'account_status'=>'active']);$this->assertDatabaseHas('users',['id'=>$external->id,'account_status'=>'active']);}
 public function test_admin_cannot_create_or_invite_other_admin():void{$u=$this->user();$this->actingAs($u)->postJson('/api/v1/people',['name'=>'Other','email'=>'other@example.test','type'=>'staff','programme_id'=>$this->pid(),'role_ids'=>[$this->role('Programme Administrator')],'mode'=>'invite'])->assertForbidden();}
 public function test_revoke_permission_overrides_role_immediately():void{$m=$this->master();$u=$this->user();$this->actingAs($m)->patchJson('/api/v1/people/'.$u->id,['action'=>'access','programme_id'=>$this->pid(),'role_ids'=>[$this->role('Programme Administrator')],'overrides'=>[['permission'=>'people.manage','allowed'=>false]]])->assertOk();$this->actingAs($u)->getJson('/api/v1/people')->assertForbidden();$this->assertDatabaseHas('audit_events',['action'=>'account.access','subject_id'=>$u->id]);}
 public function test_self_and_master_are_protected():void{$m=$this->master();$u=$this->user();$this->actingAs($u)->patchJson('/api/v1/people/'.$m->id,['action'=>'suspend'])->assertForbidden();$this->actingAs($m)->patchJson('/api/v1/people/'.$m->id,['action'=>'suspend'])->assertForbidden();}
 public function test_suspension_and_expiry_block_existing_sessions():void{$m=$this->master();$u=$this->user();$this->actingAs($m)->patchJson('/api/v1/people/'.$u->id,['action'=>'suspend'])->assertOk();$this->actingAs($u->fresh())->getJson('/api/v1/people')->assertForbidden();$u->account_status='active';$u->access_expires_at=now()->subMinute();$u->save();$this->actingAs($u)->getJson('/api/v1/people')->assertForbidden();}
 public function test_scope_cannot_cross_programmes():void{$u=$this->user();$pid=DB::table('programmes')->insertGetId(['name'=>'Other','code'=>'OTHER','created_at'=>now(),'updated_at'=>now()]);$target=$this->user('Evaluator',$pid);$this->actingAs($u)->patchJson('/api/v1/people/'.$target->id,['action'=>'suspend'])->assertNotFound();$this->getJson('/api/v1/people')->assertJsonMissing(['email'=>$target->email]);}
 public function test_allocation_persists_every_role_lead_template_deadline():void{$admin=$this->user();$i=$this->idea();$d=$this->allocation();$this->actingAs($admin)->putJson('/api/v1/applications/'.$i->id.'/allocation',$d)->assertOk();$this->assertDatabaseHas('review_assignments',['idea_id'=>$i->id,'user_id'=>$d['lead_id'],'is_lead'=>true,'active'=>true]);$this->assertDatabaseHas('review_assignments',['idea_id'=>$i->id,'kind'=>'adjudication']);$this->assertDatabaseHas('ideas',['id'=>$i->id,'status'=>'assigned']);$this->assertDatabaseHas('audit_events',['action'=>'review.allocated']);}
 public function test_independence_missing_data_and_bad_lead_are_rejected():void{$i=$this->idea();$d=$this->allocation();$this->actingAs($this->user())->putJson('/api/v1/applications/'.$i->id.'/allocation',[...$d,'adjudicator_id'=>$d['lead_id']])->assertUnprocessable();$this->putJson('/api/v1/applications/'.$i->id.'/allocation',[...$d,'lead_id'=>$d['adjudicator_id']])->assertUnprocessable();$i->complete=75;$i->save();$this->putJson('/api/v1/applications/'.$i->id.'/allocation',$d)->assertUnprocessable();$this->assertDatabaseCount('review_assignments',0);}
 public function test_inactive_reviewer_and_foreign_template_rejected():void{$i=$this->idea();$d=$this->allocation();$u=User::find($d['lead_id']);$u->account_status='suspended';$u->save();$this->actingAs($this->user())->putJson('/api/v1/applications/'.$i->id.'/allocation',$d)->assertUnprocessable();$this->assertDatabaseCount('review_assignments',0);}
 public function test_reassignment_preserves_history_and_submitted_records():void{$i=$this->idea();$d=$this->allocation();$this->actingAs($this->user())->putJson('/api/v1/applications/'.$i->id.'/allocation',$d)->assertOk();$this->putJson('/api/v1/applications/'.$i->id.'/allocation',$d)->assertUnprocessable();$this->putJson('/api/v1/applications/'.$i->id.'/allocation',[...$d,'reason'=>'Deadline extended.'])->assertOk();$this->assertSame(2,DB::table('review_assignments')->where('active',false)->count());DB::table('review_assignments')->where('active',true)->update(['status'=>'submitted','submitted_at'=>now()]);$this->putJson('/api/v1/applications/'.$i->id.'/allocation',[...$d,'reason'=>'Change reviewer.'])->assertUnprocessable();}
 public function test_template_locked_once_review_starts():void{$i=$this->idea();$d=$this->allocation();$this->actingAs($this->user())->putJson('/api/v1/applications/'.$i->id.'/allocation',$d)->assertOk();DB::table('review_assignments')->where('kind','evaluation')->update(['started_at'=>now(),'status'=>'in_progress']);$this->putJson('/api/v1/applications/'.$i->id.'/allocation',[...$d,'template_id'=>$this->template('evaluation'),'reason'=>'Try new scoring.'])->assertUnprocessable();$this->assertSame(2,DB::table('review_assignments')->where('active',true)->count());}
 public function test_independent_template_can_be_created_edited_and_deleted():void{$this->actingAs($this->user());$data=['programme_id'=>$this->pid(),'name'=>'Innovation','kind'=>'evaluation','criteria'=>[['name'=>'Feasibility','max'=>40]]];$id=$this->postJson('/api/v1/review-templates',$data)->assertCreated()->json('id');$this->getJson('/api/v1/review-templates')->assertJsonFragment(['name'=>'Innovation','use_count'=>0]);$this->patchJson('/api/v1/review-templates/'.$id,[...$data,'name'=>'Business model','criteria'=>[['name'=>'Viability','max'=>60]]])->assertOk();$this->assertDatabaseHas('review_templates',['id'=>$id,'name'=>'Business model','version'=>1]);$this->deleteJson('/api/v1/review-templates/'.$id)->assertNoContent();$this->assertDatabaseMissing('review_templates',['id'=>$id]);$this->assertDatabaseHas('audit_events',['action'=>'template.deleted','subject_id'=>$id]);}
 public function test_template_used_in_review_cannot_be_edited_or_deleted():void{$i=$this->idea();$d=$this->allocation();$this->actingAs($this->user())->putJson('/api/v1/applications/'.$i->id.'/allocation',$d)->assertOk();$changes=['programme_id'=>$this->pid(),'name'=>'Changed','kind'=>'evaluation','criteria'=>[['name'=>'Innovation','max'=>20]]];$this->patchJson('/api/v1/review-templates/'.$d['template_id'],$changes)->assertStatus(409);$this->deleteJson('/api/v1/review-templates/'.$d['template_id'])->assertStatus(409);$this->assertDatabaseHas('review_templates',['id'=>$d['template_id'],'name'=>'Criteria']);}
 public function test_revoked_invitation_cannot_activate():void{$m=$this->master();$r=$this->actingAs($m)->postJson('/api/v1/people',['name'=>'Invited','email'=>'invite@example.test','type'=>'staff','programme_id'=>$this->pid(),'role_ids'=>[$this->role('Viewer')],'mode'=>'invite'])->assertCreated();parse_str(parse_url($r->json('activation_url'),PHP_URL_QUERY),$q);$this->patchJson('/api/v1/people/'.$r->json('data.id'),['action'=>'revoke'])->assertOk();$this->postJson('/api/v1/activate',['token'=>$q['token'],'password'=>'Password-new-123','password_confirmation'=>'Password-new-123','confidentiality'=>true])->assertUnprocessable();}
 public function test_mfa_is_required_for_privileged_accounts():void{$u=$this->user();$this->actingAs($u)->withSession(['mfa_user_id'=>null])->getJson('/api/v1/people')->assertForbidden();$this->getJson('/api/v1/me')->assertOk();}
 public function test_staff_and_external_reviewers_require_authenticator():void{$staff=$this->user('Viewer');$this->actingAs($staff)->withSession(['mfa_user_id'=>null])->getJson('/api/v1/applications')->assertForbidden();$this->getJson('/api/v1/me')->assertJsonPath('user.mfa_required',true);$external=$this->user('Viewer');$external->member_type='external';$external->save();$this->actingAs($external)->withSession(['mfa_user_id'=>null])->getJson('/api/v1/applications')->assertForbidden();$this->getJson('/api/v1/me')->assertJsonPath('user.mfa_required',true);$this->postJson('/api/v1/mfa/setup')->assertOk();}
 public function test_external_accounts_cannot_receive_staff_administration_access():void{$master=$this->master();$this->actingAs($master)->postJson('/api/v1/people',['name'=>'External Admin','email'=>'external-admin@example.test','type'=>'external','programme_id'=>$this->pid(),'role_ids'=>[$this->role('Programme Administrator')],'mode'=>'create'])->assertStatus(422);$external=$this->user('Evaluator');$external->member_type='external';$external->save();$this->actingAs($master)->patchJson('/api/v1/people/'.$external->id,['action'=>'access','programme_id'=>$this->pid(),'role_ids'=>[$this->role('Programme Administrator')]])->assertNotFound();$this->patchJson('/api/v1/people/'.$external->id,['action'=>'access','programme_id'=>$this->pid(),'role_ids'=>[$this->role('Evaluator')],'overrides'=>[['permission'=>'people.manage','allowed'=>true]]])->assertNotFound();}
 public function test_totp_enrolment_and_replay_protection():void{$u=$this->user();$r=$this->actingAs($u)->postJson('/api/v1/mfa/setup')->assertOk();$code=\App\Services\Totp::code($r->json('secret'),intdiv(time(),30));$this->postJson('/api/v1/mfa/verify',['code'=>$code])->assertOk();$this->postJson('/api/v1/mfa/verify',['code'=>$code])->assertUnprocessable();$this->getJson('/api/v1/people')->assertOk();}
 public function test_started_templates_and_unavailable_reviewers_are_protected():void{$i=$this->idea();$d=$this->allocation();$u=User::find($d['lead_id']);$u->availability='unavailable';$u->save();$this->actingAs($this->user())->putJson('/api/v1/applications/'.$i->id.'/allocation',$d)->assertUnprocessable();}

 public function test_evaluator_allocation_can_precede_adjudication():void{$idea=$this->idea();$data=$this->allocation();$data['adjudicator_id']=null;$data['adjudication_template_id']=null;$this->actingAs($this->master())->putJson('/api/v1/applications/'.$idea->id.'/allocation',$data)->assertOk();$this->assertDatabaseHas('review_assignments',['idea_id'=>$idea->id,'kind'=>'evaluation','active'=>true]);$this->assertDatabaseMissing('review_assignments',['idea_id'=>$idea->id,'kind'=>'adjudication']);}
 public function test_applicant_drafts_are_private_and_submission_is_locked():void{$u=$this->user('Viewer');$u->member_type='applicant';$u->email_verified_at=now();$u->save();$d=['programme_id'=>$this->pid(),'title'=>'Applicant idea','category'=>'Agriculture','location'=>'Maun','summary'=>'Summary','problem'=>'Problem','solution'=>'Solution','submit'=>false,'form_version'=>'online-v2','declaration'=>true,'form_answers'=>['customers'=>'Customers','business_stage'=>'Idea / concept','category_answers'=>['Agriculture'=>['activity'=>'Farming','resources'=>'Land','market'=>'Buyers','validation_plan'=>'Run a small local pilot']]]];$id=$this->actingAs($u)->postJson('/api/v1/applicant/applications',$d)->assertOk()->json('data.id');$other=$this->user('Viewer');$other->member_type='applicant';$other->save();$this->actingAs($other)->putJson('/api/v1/applicant/applications/'.$id,$d)->assertNotFound();$this->getJson('/api/v1/applicant/applications')->assertJsonMissing(['title'=>'Applicant idea']);$this->actingAs($u)->postJson('/api/v1/applicant/applications/'.$id.'/attachments',['name'=>'proposal.pdf','content'=>base64_encode("%PDF-1.4\n%%EOF"),'kind'=>'proposal','category'=>'Agriculture','template_version'=>config('application_form.version')])->assertOk();$this->putJson('/api/v1/applicant/applications/'.$id,[...$d,'submit'=>true])->assertOk();$this->putJson('/api/v1/applicant/applications/'.$id,$d)->assertStatus(409);}

 public function test_evaluator_sees_only_own_active_allocations():void{$idea=$this->idea();$data=$this->allocation();$this->actingAs($this->master())->putJson('/api/v1/applications/'.$idea->id.'/allocation',$data)->assertOk();$e=User::find($data['lead_id']);$this->actingAs($e)->getJson('/api/v1/my-evaluations')->assertOk()->assertJsonFragment(['title'=>'Business idea']);$this->assertSame([$this->pid()],$this->getJson('/api/v1/me')->json('user.permissions')['reviews.evaluate']);$other=$this->user('Evaluator');$this->actingAs($other)->getJson('/api/v1/my-evaluations')->assertOk()->assertJsonCount(0,'data');$this->actingAs($this->user('Viewer'))->getJson('/api/v1/my-evaluations')->assertForbidden();}
 public function test_reports_include_all_authorised_submissions_and_exclude_other_programmes_and_drafts():void{
  $viewer=$this->user('Viewer');for($n=0;$n<55;$n++)$this->idea();
  $draft=$this->idea();$draft->status='draft';$draft->title='Private draft';$draft->save();
  $otherId=DB::table('programmes')->insertGetId(['name'=>'Other','code'=>'OTHERREPORT','created_at'=>now(),'updated_at'=>now()]);$other=$this->idea();$other->programme_id=$otherId;$other->title='Other programme';$other->save();
  DB::table('access_overrides')->insert(['user_id'=>$viewer->id,'programme_id'=>$this->pid(),'permission'=>'applications.view','allowed'=>false]);
  $this->actingAs($viewer)->getJson('/api/v1/reports/applications')->assertOk()->assertJsonCount(55,'data')->assertJsonMissing(['title'=>'Private draft'])->assertJsonMissing(['title'=>'Other programme']);
  $this->actingAs($this->user('Evaluator'))->getJson('/api/v1/reports/applications')->assertForbidden();
 }
}
